-- Tables only the conformance suite's tests use (../sqlite/conformance.sql), applied after the fixture schema.
CREATE TABLE stamps (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT, seconds BIGINT, milliseconds BIGINT);

CREATE TABLE entries (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);

-- TEXT, as an app may keep JSON: a cell that isn't JSON can then be stored, and must fail to load.
CREATE TABLE json_docs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, folder_id BIGINT, settings TEXT, secret TEXT);

CREATE TABLE json_folders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY);

CREATE TABLE guarded_stamps (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, seconds BIGINT, milliseconds BIGINT, mapped_at BIGINT, iso TIMESTAMPTZ);

-- meta is JSON, which keeps its text as written, as a raw query in its tests reads it (jsonb-text).
CREATE TABLE typed_posts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT, published_at TIMESTAMPTZ, seconds BIGINT, milliseconds BIGINT, featured BOOLEAN, rating BIGINT, score DOUBLE PRECISION, meta JSON, secret TEXT);

CREATE TABLE typed_samples (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, label TEXT, enabled BOOLEAN, settings JSONB, stamp TIMESTAMPTZ, secret TEXT);

-- An enum stored as text (status) and one stored as integers (priority), #340.
CREATE TABLE articles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT, status TEXT, priority BIGINT);

-- Bytes (#20): a file's contents (data) and a hash to look one up by (digest).
CREATE TABLE attachments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT, data BYTEA, digest BYTEA);

-- Custom types (#20): a price kept as integer cents, and a list of sizes kept as text.
CREATE TABLE listings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT, price BIGINT, sizes TEXT);

-- Dates, decimals and times (#391): an amount, the day it's booked on, and when it starts.
CREATE TABLE ledger_lines (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, label TEXT, amount NUMERIC, booked_on DATE, starts_at TIME, price NUMERIC(10, 2));

-- Calculations (#344): a column named like the alias a calculation selects its values as.
CREATE TABLE readings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, value BIGINT, price BIGINT);

-- Associations through another (#59): users' projects through their assignments.
CREATE TABLE projects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, archived BIGINT NOT NULL DEFAULT 0);
CREATE TABLE assignments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES users (id), project_id BIGINT REFERENCES projects (id), role TEXT);

-- Polymorphic associations (#60): a remark on a post or a photo, by its type and id.
CREATE TABLE photos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT);
CREATE TABLE remarks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, body TEXT, commentable_type TEXT, commentable_id BIGINT, user_id BIGINT);
